constexpr int kSampleRate = 44100;

// A decoded clip: interleaved stereo, 16-bit, 44.1 kHz
struct Clip {
    std::string name;
    std::vector<int16_t> pcm;
    float length = 0.f;  // seconds
};

// Reads 8/16/24/32-bit PCM or 32-bit float WAV (mono or stereo, any sample rate).
std::shared_ptr<Clip> LoadWav(const std::string& path, std::string* error);

struct Player {
    virtual ~Player() = default;
    virtual void Play(const std::shared_ptr<Clip>& clip, float volume) = 0;
    virtual void StopAll() = 0;
};

// OpenSL ES based mixer (audio_sles.cpp)
class Mixer : public Player {
public:
    bool Start();
    void Play(const std::shared_ptr<Clip>& clip, float volume) override;
    void StopAll() override;
};
extern Mixer g_mixer;


