// ===================== log.cpp =====================

#include <android/log.h>
#include <sys/stat.h>

#include <cstdarg>
#include <cstdio>
#include <ctime>
#include <mutex>

static std::mutex g_logMu;
static FILE* g_file = nullptr;

void LogInit(const std::string& path) {
    std::lock_guard<std::mutex> lock(g_logMu);
    if (g_file) fclose(g_file);
    struct stat st {};
    // keep the log small: start over once it grows past 512 KB
    const char* mode = (stat(path.c_str(), &st) == 0 && st.st_size > 512 * 1024) ? "w" : "a";
    g_file = fopen(path.c_str(), mode);
}

void Logf(const char* fmt, ...) {
    char buf[1024];
    va_list ap;
    va_start(ap, fmt);
    vsnprintf(buf, sizeof buf, fmt, ap);
    va_end(ap);

    __android_log_print(ANDROID_LOG_INFO, "MoanMod", "%s", buf);

    std::lock_guard<std::mutex> lock(g_logMu);
    if (!g_file) return;
    time_t t = time(nullptr);
    struct tm tmv {};
    localtime_r(&t, &tmv);
    char ts[32];
    strftime(ts, sizeof ts, "%H:%M:%S", &tmv);
    fprintf(g_file, "[%s] %s\n", ts, buf);
    fflush(g_file);
}


