#include <cstdio>
#include <cstdlib>
#include <fstream>
#include <map>
#include <sstream>

static std::string Trim(const std::string& s) {
    size_t a = s.find_first_not_of(" \t\r\n");
    if (a == std::string::npos) return "";
    size_t b = s.find_last_not_of(" \t\r\n");
    return s.substr(a, b - a + 1);
}

static std::vector<float> ParseList(const std::string& v, const std::vector<float>& fallback) {
    std::vector<float> out;
    std::stringstream ss(v);
    std::string item;
    while (std::getline(ss, item, ',')) {
        item = Trim(item);
        if (item.empty()) continue;
        out.push_back(strtof(item.c_str(), nullptr));
    }
    return out.empty() ? fallback : out;
}

static std::string ListToString(const std::vector<float>& v) {
    std::string s;
    char buf[32];
    for (size_t i = 0; i < v.size(); i++) {
        snprintf(buf, sizeof buf, "%g", v[i]);
        if (i) s += ", ";
        s += buf;
    }
    return s;
}

static void WriteDefaults(const std::string& path, const Config& c) {
    FILE* f = fopen(path.c_str(), "w");
    if (!f) return;
    fprintf(f,
        "# MoanMod (Android native) settings. Restart the game after editing.\n"
        "enabled = %d\n"
        "dump_classes = %d            # 1 = write game class info to moanmod.log (for debugging)\n"
        "\n"
        "volume = %g                  # 0..1\n"
        "sex_scene_start_cooldown = %g\n"
        "\n"
        "# pleasure thresholds\n"
        "check_interval = %g\n"
        "base_low = %g                # threshold at 0 pleasure (less sensitive)\n"
        "base_high = %g               # threshold at pleasure_cap (more sensitive)\n"
        "pleasure_cap = %g\n"
        "cowgirl_multiplier = %g\n"
        "\n"
        "# sex moan clusters\n"
        "cluster_max_moans = %d\n"
        "cluster_delay_min = %g\n"
        "cluster_delay_max = %g\n"
        "repeat_cooldown = %d\n"
        "repeat_chance = %g\n"
        "cluster_probabilities = %s\n"
        "\n"
        "# breathing\n"
        "breath_delay_min = %g\n"
        "breath_delay_max = %g\n"
        "breath_window = %g\n"
        "breath_probabilities = %s\n",
        c.enabled, c.dumpClasses, c.volume, c.sexSceneStartCooldown, c.checkInterval, c.baseLow,
        c.baseHigh, c.pleasureCap, c.cowgirlMultiplier, c.clusterMaxMoans, c.clusterDelayMin,
        c.clusterDelayMax, c.repeatCooldown, c.repeatChance, ListToString(c.clusterProbabilities).c_str(),
        c.breathDelayMin, c.breathDelayMax, c.breathWindow, ListToString(c.breathProbabilities).c_str());
    fclose(f);
}

void LoadConfig(const std::string& path, Config& c) {
    std::ifstream in(path);
    if (!in) {
        WriteDefaults(path, c);
        Logf("Created default config: %s", path.c_str());
        return;
    }

    std::map<std::string, std::string> kv;
    std::string line;
    while (std::getline(in, line)) {
        size_t hash = line.find('#');
        if (hash != std::string::npos) line = line.substr(0, hash);
        size_t eq = line.find('=');
        if (eq == std::string::npos) continue;
        kv[Trim(line.substr(0, eq))] = Trim(line.substr(eq + 1));
    }

    auto F = [&](const char* k, float& v) { auto it = kv.find(k); if (it != kv.end()) v = strtof(it->second.c_str(), nullptr); };
    auto I = [&](const char* k, int& v) { auto it = kv.find(k); if (it != kv.end()) v = atoi(it->second.c_str()); };
    auto B = [&](const char* k, bool& v) { auto it = kv.find(k); if (it != kv.end()) v = atoi(it->second.c_str()) != 0; };
    auto L = [&](const char* k, std::vector<float>& v) { auto it = kv.find(k); if (it != kv.end()) v = ParseList(it->second, v); };

    B("enabled", c.enabled);
    B("dump_classes", c.dumpClasses);
    F("volume", c.volume);
    F("sex_scene_start_cooldown", c.sexSceneStartCooldown);
    F("check_interval", c.checkInterval);
    F("base_low", c.baseLow);
    F("base_high", c.baseHigh);
    F("pleasure_cap", c.pleasureCap);
    F("cowgirl_multiplier", c.cowgirlMultiplier);
    I("cluster_max_moans", c.clusterMaxMoans);
    F("cluster_delay_min", c.clusterDelayMin);
    F("cluster_delay_max", c.clusterDelayMax);
    I("repeat_cooldown", c.repeatCooldown);
    F("repeat_chance", c.repeatChance);
    L("cluster_probabilities", c.clusterProbabilities);
    F("breath_delay_min", c.breathDelayMin);
    F("breath_delay_max", c.breathDelayMax);
    F("breath_window", c.breathWindow);
    L("breath_probabilities", c.breathProbabilities);

    if (c.pleasureCap <= 0.0001f) c.pleasureCap = 0.8f;
    if (c.checkInterval < 0.02f) c.checkInterval = 0.02f;
    Logf("Config loaded: %s", path.c_str());
}


// ===================== audio_wav.cpp =====================

#include <cmath>
#include <cstring>
#include <fstream>
#include <iterator>

static uint16_t Rd16(const uint8_t* p) { return (uint16_t)(p[0] | (p[1] << 8)); }
static uint32_t Rd32(const uint8_t* p) { return (uint32_t)p[0] | ((uint32_t)p[1] << 8) | ((uint32_t)p[2] << 16) | ((uint32_t)p[3] << 24); }

static std::string BaseName(const std::string& path) {
    size_t slash = path.find_last_of('/');
    std::string f = slash == std::string::npos ? path : path.substr(slash + 1);
    size_t dot = f.find_last_of('.');
    return dot == std::string::npos ? f : f.substr(0, dot);
}

std::shared_ptr<Clip> LoadWav(const std::string& path, std::string* error) {
    auto fail = [&](const char* msg) -> std::shared_ptr<Clip> {
        if (error) *error = msg;
        return nullptr;
    };

    std::ifstream in(path, std::ios::binary);
    if (!in) return fail("cannot open file");
    std::vector<uint8_t> b((std::istreambuf_iterator<char>(in)), std::istreambuf_iterator<char>());
    if (b.size() < 44 || memcmp(b.data(), "RIFF", 4) != 0 || memcmp(b.data() + 8, "WAVE", 4) != 0)
        return fail("not a RIFF/WAVE file");

    int fmtTag = 0, channels = 0, bits = 0;
    uint32_t rate = 0;
    const uint8_t* data = nullptr;
    size_t dataLen = 0;

    size_t pos = 12;
    while (pos + 8 <= b.size()) {
        const uint8_t* id = &b[pos];
        size_t sz = Rd32(&b[pos + 4]);
        size_t body = pos + 8;
        if (body + sz > b.size()) sz = b.size() - body;  // truncated or streaming-style size

        if (memcmp(id, "fmt ", 4) == 0 && sz >= 16) {
            fmtTag = Rd16(&b[body]);
            channels = Rd16(&b[body + 2]);
            rate = Rd32(&b[body + 4]);
            bits = Rd16(&b[body + 14]);
            if (fmtTag == 0xFFFE && sz >= 26) fmtTag = Rd16(&b[body + 24]);  // WAVE_FORMAT_EXTENSIBLE
        } else if (memcmp(id, "data", 4) == 0) {
            data = &b[body];
            dataLen = sz;
            break;
        }
        pos = body + sz + (sz & 1);
    }

    if (!data || channels < 1 || rate == 0) return fail("missing fmt/data chunk");
    bool isFloat = (fmtTag == 3);
    if (!(fmtTag == 1 || isFloat)) return fail("unsupported WAV encoding (use PCM)");
    if (isFloat && bits != 32) return fail("unsupported float WAV");
    if (!isFloat && bits != 8 && bits != 16 && bits != 24 && bits != 32) return fail("unsupported bit depth");

    const int bytesPer = bits / 8;
    const size_t frames = dataLen / (size_t)(bytesPer * channels);
    if (frames < 2) return fail("empty audio data");

    auto sample = [&](size_t frame, int ch) -> float {
        const uint8_t* p = data + (frame * channels + ch) * bytesPer;
        if (isFloat) { float f; memcpy(&f, p, 4); return f; }
        switch (bits) {
            case 8:  return ((int)p[0] - 128) / 128.0f;
            case 16: return (int16_t)Rd16(p) / 32768.0f;
            case 24: { int32_t v = (int32_t)((uint32_t)p[0] << 8 | (uint32_t)p[1] << 16 | (uint32_t)p[2] << 24); return (v >> 8) / 8388608.0f; }
            default: return (int32_t)Rd32(p) / 2147483648.0f;
        }
    };
    auto stereo = [&](size_t frame, float& l, float& r) {
        l = sample(frame, 0);
        r = channels > 1 ? sample(frame, 1) : l;
    };

    auto clip = std::make_shared<Clip>();
    clip->name = BaseName(path);

    const size_t outFrames = (size_t)((double)frames * kSampleRate / rate);
    clip->pcm.resize(outFrames * 2);
    for (size_t i = 0; i < outFrames; i++) {
        double src = (double)i * rate / kSampleRate;
        size_t i0 = (size_t)src;
        size_t i1 = i0 + 1 < frames ? i0 + 1 : i0;
        float t = (float)(src - (double)i0);
        float l0, r0, l1, r1;
        stereo(i0, l0, r0);
        stereo(i1, l1, r1);
        float l = l0 + (l1 - l0) * t, r = r0 + (r1 - r0) * t;
        l = l > 1.f ? 1.f : (l < -1.f ? -1.f : l);
        r = r > 1.f ? 1.f : (r < -1.f ? -1.f : r);
        clip->pcm[i * 2] = (int16_t)lrintf(l * 32767.f);
        clip->pcm[i * 2 + 1] = (int16_t)lrintf(r * 32767.f);
    }
    clip->length = (float)outFrames / kSampleRate;
    return clip;
}


// ===================== audio_sles.cpp =====================


#include <SLES/OpenSLES.h>
#include <SLES/OpenSLES_Android.h>

#include <algorithm>
#include <mutex>

Mixer g_mixer;

namespace {

constexpr int kFrames = 1024;     // frames per buffer (~23 ms)
constexpr int kBuffers = 3;
constexpr size_t kMaxVoices = 8;

struct Voice {
    std::shared_ptr<Clip> clip;
    size_t pos = 0;  // in frames
    float vol = 1.f;
};

std::mutex g_mu;
std::vector<Voice> g_voices;

SLObjectItf g_engineObj = nullptr;
SLEngineItf g_engine = nullptr;
SLObjectItf g_mixObj = nullptr;
SLObjectItf g_playerObj = nullptr;
SLPlayItf g_play = nullptr;
SLAndroidSimpleBufferQueueItf g_queue = nullptr;

int16_t g_buf[kBuffers][kFrames * 2];
int g_cur = 0;
bool g_started = false;

void FillAndEnqueue(SLAndroidSimpleBufferQueueItf bq) {
    int16_t* out = g_buf[g_cur];
    g_cur = (g_cur + 1) % kBuffers;

    float acc[kFrames * 2];
    std::fill(acc, acc + kFrames * 2, 0.f);

    {
        std::lock_guard<std::mutex> lock(g_mu);
        for (auto& v : g_voices) {
            const size_t total = v.clip->pcm.size() / 2;
            const size_t n = std::min<size_t>(kFrames, total - v.pos);
            const int16_t* src = v.clip->pcm.data() + v.pos * 2;
            for (size_t i = 0; i < n; i++) {
                acc[i * 2] += src[i * 2] * v.vol;
                acc[i * 2 + 1] += src[i * 2 + 1] * v.vol;
            }
            v.pos += n;
        }
        g_voices.erase(std::remove_if(g_voices.begin(), g_voices.end(),
                                      [](const Voice& v) { return v.pos >= v.clip->pcm.size() / 2; }),
                       g_voices.end());
    }

    for (int i = 0; i < kFrames * 2; i++) {
        float s = acc[i];
        s = s > 32767.f ? 32767.f : (s < -32768.f ? -32768.f : s);
        out[i] = (int16_t)s;
    }
    (*bq)->Enqueue(bq, out, sizeof(int16_t) * kFrames * 2);
}

void BufferDone(SLAndroidSimpleBufferQueueItf bq, void*) { FillAndEnqueue(bq); }

}  // namespace

bool Mixer::Start() {
    if (g_started) return true;

    if (slCreateEngine(&g_engineObj, 0, nullptr, 0, nullptr, nullptr) != SL_RESULT_SUCCESS) { Logf("OpenSL: slCreateEngine failed"); return false; }
    if ((*g_engineObj)->Realize(g_engineObj, SL_BOOLEAN_FALSE) != SL_RESULT_SUCCESS) { Logf("OpenSL: engine Realize failed"); return false; }
    if ((*g_engineObj)->GetInterface(g_engineObj, SL_IID_ENGINE, &g_engine) != SL_RESULT_SUCCESS) { Logf("OpenSL: no engine interface"); return false; }
    if ((*g_engine)->CreateOutputMix(g_engine, &g_mixObj, 0, nullptr, nullptr) != SL_RESULT_SUCCESS) { Logf("OpenSL: CreateOutputMix failed"); return false; }
    if ((*g_mixObj)->Realize(g_mixObj, SL_BOOLEAN_FALSE) != SL_RESULT_SUCCESS) { Logf("OpenSL: mix Realize failed"); return false; }

    SLDataLocator_AndroidSimpleBufferQueue locQueue = {SL_DATALOCATOR_ANDROIDSIMPLEBUFFERQUEUE, (SLuint32)kBuffers};
    SLDataFormat_PCM fmt = {SL_DATAFORMAT_PCM,
                            2,
                            SL_SAMPLINGRATE_44_1,
                            SL_PCMSAMPLEFORMAT_FIXED_16,
                            SL_PCMSAMPLEFORMAT_FIXED_16,
                            SL_SPEAKER_FRONT_LEFT | SL_SPEAKER_FRONT_RIGHT,
                            SL_BYTEORDER_LITTLEENDIAN};
    SLDataSource src = {&locQueue, &fmt};
    SLDataLocator_OutputMix locMix = {SL_DATALOCATOR_OUTPUTMIX, g_mixObj};
    SLDataSink sink = {&locMix, nullptr};

    const SLInterfaceID ids[1] = {SL_IID_ANDROIDSIMPLEBUFFERQUEUE};
    const SLboolean req[1] = {SL_BOOLEAN_TRUE};
    if ((*g_engine)->CreateAudioPlayer(g_engine, &g_playerObj, &src, &sink, 1, ids, req) != SL_RESULT_SUCCESS) { Logf("OpenSL: CreateAudioPlayer failed"); return false; }
    if ((*g_playerObj)->Realize(g_playerObj, SL_BOOLEAN_FALSE) != SL_RESULT_SUCCESS) { Logf("OpenSL: player Realize failed"); return false; }
    if ((*g_playerObj)->GetInterface(g_playerObj, SL_IID_PLAY, &g_play) != SL_RESULT_SUCCESS) { Logf("OpenSL: no play interface"); return false; }
    if ((*g_playerObj)->GetInterface(g_playerObj, SL_IID_ANDROIDSIMPLEBUFFERQUEUE, &g_queue) != SL_RESULT_SUCCESS) { Logf("OpenSL: no buffer queue"); return false; }
    if ((*g_queue)->RegisterCallback(g_queue, BufferDone, nullptr) != SL_RESULT_SUCCESS) { Logf("OpenSL: RegisterCallback failed"); return false; }

    // prime the queue with silence first; once playing, the callback keeps it filled
    for (int i = 0; i < kBuffers; i++) FillAndEnqueue(g_queue);
    if ((*g_play)->SetPlayState(g_play, SL_PLAYSTATE_PLAYING) != SL_RESULT_SUCCESS) { Logf("OpenSL: SetPlayState failed"); return false; }

    g_started = true;
    Logf("OpenSL ES audio started");
    return true;
}

void Mixer::Play(const std::shared_ptr<Clip>& clip, float volume) {
    if (!g_started || !clip || clip->pcm.empty()) return;
    std::lock_guard<std::mutex> lock(g_mu);
    if (g_voices.size() >= kMaxVoices) g_voices.erase(g_voices.begin());
    g_voices.push_back(Voice{clip, 0, volume});
}

void Mixer::StopAll() {
    std::lock_guard<std::mutex> lock(g_mu);
    g_voices.clear();
}


