#include <algorithm>
#include <cmath>

static float Clamp01(float v) { return v < 0.f ? 0.f : (v > 1.f ? 1.f : v); }

// ============================== AudioBank ==============================

void AudioBank::Add(AType t, std::shared_ptr<Clip> clip) { cols_[t].clips.push_back(Entry{std::move(clip), 0}); }

void AudioBank::Clear() { for (auto& c : cols_) { c.clips.clear(); c.last = -1; } }

float AudioBank::LastLength(AType t) const {
    const Col& c = cols_[t];
    return c.last >= 0 ? c.clips[c.last].clip->length : 0.f;
}

std::string AudioBank::LastName(AType t) const {
    const Col& c = cols_[t];
    return c.last >= 0 ? c.clips[c.last].clip->name : "Unknown";
}

float AudioBank::Rand01() { return std::uniform_real_distribution<float>(0.f, 1.f)(rng_); }

int AudioBank::PickAvailable(Col& col, bool useCooldowns) {
    if (!useCooldowns) return (int)(rng_() % col.clips.size());

    std::vector<int> avail;
    for (int i = 0; i < (int)col.clips.size(); i++)
        if (col.clips[i].cooldown <= 0) avail.push_back(i);
    if (avail.empty()) {
        int least = 0;
        for (int i = 1; i < (int)col.clips.size(); i++)
            if (col.clips[i].cooldown < col.clips[least].cooldown) least = i;
        col.clips[least].cooldown = 0;
        avail.push_back(least);
    }
    return avail[rng_() % avail.size()];
}

int AudioBank::Select(AType t, bool useCooldowns) {
    Col& col = cols_[t];
    if (col.clips.empty()) return -1;

    int sel = -1;
    bool maybeRepeat = useCooldowns && col.last >= 0 && col.clips[col.last].cooldown <= 0;
    if (maybeRepeat && Rand01() < cfg_.repeatChance) sel = col.last;
    if (sel < 0) sel = PickAvailable(col, useCooldowns);

    col.last = sel;
    if (!useCooldowns) return sel;

    col.clips[sel].cooldown = cfg_.repeatCooldown;
    for (int i = 0; i < (int)col.clips.size(); i++)
        if (i != sel && col.clips[i].cooldown > 0) col.clips[i].cooldown--;
    return sel;
}

float AudioBank::Play(AType t, bool useCooldowns, float volumeMul) {
    int s = Select(t, useCooldowns);
    if (s < 0) return 0.f;
    const auto& clip = cols_[t].clips[s].clip;
    player_->Play(clip, Clamp01(cfg_.volume * volumeMul));
    return clip->length;
}

void AudioBank::ResetCooldowns(AType t) {
    for (auto& e : cols_[t].clips) e.cooldown = 0;
    cols_[t].last = -1;
}

// ============================== MoanLogic ==============================

float MoanLogic::Rand(float a, float b) { return a + (b - a) * std::uniform_real_distribution<float>(0.f, 1.f)(rng_); }

void MoanLogic::OnBrainFound() { pleasureTimer_ = cfg_.checkInterval; }

void MoanLogic::ResetAll() {
    SexReset();
    BreathReset();
    CumReset();
}

void MoanLogic::Update(const Ctx& ctx, float dt) {
    cur_ = ctx;
    time_ += dt;

    bool inSex = ctx.scene != SceneType::None;
    if (inSex && !wasInSex_) {
        Logf("=== Entered Sex Scene (%d) ===", (int)ctx.scene);
        if (!ctx.advancedAi) Logf("Advanced AI not active - moaning disabled");
        startCooldown_ = cfg_.sexSceneStartCooldown;
        wasInSex_ = true;
    } else if (!inSex && wasInSex_) {
        Logf("=== Exited Sex Scene ===");
        wasInSex_ = false;
        ResetAll();
    }

    if (startCooldown_ > 0.f) startCooldown_ -= dt;

    if (!inSex) return;
    if (!ctx.advancedAi) return;

    BreathTick(dt);

    if (startCooldown_ > 0.f) return;

    if (ctx.cumming && !wasCumming_) {
        Logf("=== Cumming Started ===");
        SexReset();
        BreathReset();
        OnCumStart(ctx);
    } else if (!ctx.cumming && wasCumming_) {
        OnCumEnd();
    }
    wasCumming_ = ctx.cumming;

    SexTick(dt);
    CumTick(dt);
}

// ------------------------------ breath ------------------------------

int MoanLogic::MoanCountInWindow() {
    float cutoff = time_ - cfg_.breathWindow;
    while (!timestamps_.empty() && timestamps_.front() < cutoff) timestamps_.pop_front();
    return (int)timestamps_.size();
}

bool MoanLogic::ShouldBreathe() {
    if (!bank_.Has(Breath) || lastActionWasBreath_ || cur_.talking) return false;
    if (cfg_.breathProbabilities.empty()) return false;
    int count = MoanCountInWindow();
    int tier = std::min(count / 2, (int)cfg_.breathProbabilities.size() - 1);
    return Rand01() < cfg_.breathProbabilities[tier];
}

bool MoanLogic::BreathStart(std::function<void()> onReady) {
    float length = bank_.Play(Breath, false, 1.f);
    if (length <= 0.f) return false;

    breathPlaying_ = true;
    breathTimer_ = length;
    onReady_ = std::move(onReady);
    lastActionWasBreath_ = true;
    Logf("Breath '%s'! Length: %.2fs, Moans in last %.1fs: %d", bank_.LastName(Breath).c_str(), length,
         cfg_.breathWindow, MoanCountInWindow());
    return true;
}

void MoanLogic::BreathTick(float dt) {
    if (breathPlaying_) {
        breathTimer_ -= dt;
        if (breathTimer_ <= 0.f) {
            breathPlaying_ = false;
            postBreathDelay_ = Rand(cfg_.breathDelayMin, cfg_.breathDelayMax);
        }
    }
    if (!breathPlaying_ && postBreathDelay_ > 0.f) {
        postBreathDelay_ -= dt;
        if (postBreathDelay_ <= 0.f) {
            auto cb = std::move(onReady_);
            onReady_ = nullptr;
            if (cb) cb();
        }
    }
}

void MoanLogic::BreathReset() {
    timestamps_.clear();
    lastActionWasBreath_ = false;
    breathPlaying_ = false;
    breathTimer_ = 0.f;
    postBreathDelay_ = 0.f;
    onReady_ = nullptr;
}

// ------------------------------ sex moans ------------------------------

void MoanLogic::SexReset() {
    inCluster_ = false;
    clusterCount_ = 0;
    clusterDelayTimer_ = 0.f;
    sexMoanTimer_ = 0.f;
    pleasureTimer_ = cfg_.checkInterval;
    lastPleasure_ = 0.f;
}

float MoanLogic::PleasureThreshold() const {
    float normalized = Clamp01(cur_.pleasure / cfg_.pleasureCap);
    float range = cfg_.baseLow - cfg_.baseHigh;
    float required = cfg_.baseLow - normalized * range;
    // (headpat penalty is not available in the native version)
    if (cur_.scene == SceneType::Cowgirl) required *= cfg_.cowgirlMultiplier;
    return required;
}

void MoanLogic::SexTick(float dt) {
    // cooldown between clusters
    if (sexMoanTimer_ > 0.f) {
        sexMoanTimer_ -= dt;
        if (sexMoanTimer_ <= 0.f) {
            clusterCount_ = 0;
            inCluster_ = false;
        }
    }

    // pleasure check
    pleasureTimer_ -= dt;
    if (pleasureTimer_ <= 0.f) {
        pleasureTimer_ = cfg_.checkInterval;

        float change = std::fabs(cur_.pleasure - lastPleasure_);
        lastPleasure_ = cur_.pleasure;
        float required = PleasureThreshold();

        bool canTrigger = change > required && !cur_.cumming && sexMoanTimer_ <= 0.f && !inCluster_ &&
                          !pendingEnd_ && !playingEnd_ && !cur_.talking && bank_.Has(Sex);
        if (canTrigger) {
            clusterCount_ = 1;
            inCluster_ = true;
            PlayInCluster();
        }
    }

    // continue the cluster
    if (!inCluster_ || clusterDelayTimer_ <= 0.f || BreathActive()) return;
    clusterDelayTimer_ -= dt;
    if (clusterDelayTimer_ > 0.f) return;

    if (ShouldContinueCluster() && clusterCount_ < cfg_.clusterMaxMoans) {
        clusterCount_++;
        if (ShouldBreathe()) BreathStart([this] { PlayInCluster(); });
        else PlayInCluster();
    } else {
        EndCluster();
    }
}

void MoanLogic::PlayInCluster() {
    lastActionWasBreath_ = false;
    bank_.Play(Sex, true, 1.f);
    AddMoanTimestamp();

    float length = bank_.LastLength(Sex);
    clusterDelayTimer_ = length + Rand(cfg_.clusterDelayMin, cfg_.clusterDelayMax);
    Logf("Sex moan '%s' (cluster #%d)! Clip: %.2fs", bank_.LastName(Sex).c_str(), clusterCount_, length);
}

bool MoanLogic::ShouldContinueCluster() {
    if (clusterCount_ < 1 || clusterCount_ > (int)cfg_.clusterProbabilities.size()) return false;
    return Rand01() < cfg_.clusterProbabilities[clusterCount_ - 1];
}

void MoanLogic::EndCluster() {
    sexMoanCooldown_ = SexMoanFrequency();
    sexMoanTimer_ = sexMoanCooldown_;
    inCluster_ = false;
    Logf("Cluster ended after %d moans. Cooldown: %.2fs", clusterCount_, sexMoanCooldown_);
}

float MoanLogic::SexMoanFrequency() const {
    float pleasureFactor = cur_.pleasure;
    float lustFactor = Clamp01((cur_.lust - 200.f) / 1800.f);
    float sympathyFactor = Clamp01((cur_.sympathy - 150.f) / 1350.f);
    float combined = pleasureFactor * 0.5f + lustFactor * 0.25f + sympathyFactor * 0.25f;

    float rangeMin = 3.0f - combined * 2.5f;
    float rangeMax = 5.0f - combined * 3.0f;
    float u = std::uniform_real_distribution<float>(0.f, 1.f)(rng_);
    return rangeMin + (rangeMax - rangeMin) * u;
}

// ------------------------------ cumming ------------------------------

void MoanLogic::CumReset() {
    cumMoanTimer_ = 0.f;
    cumMoanCooldown_ = kDefaultCumCooldown;
    endMoanTimer_ = 0.f;
    pendingEnd_ = false;
    playingEnd_ = false;
}

void MoanLogic::OnCumStart(const Ctx& ctx) {
    pendingEnd_ = false;
    playingEnd_ = false;
    cumMoanTimer_ = 0.f;

    Logf("Stats - Lust: %d, Sympathy: %d", ctx.lust, ctx.sympathy);
    if (ctx.sympathy <= 5 || ctx.lust <= 10) {
        Logf("Stats too low for moaning");
        return;
    }

    bank_.Play(CumStart, false, 1.f);
    AddMoanTimestamp();

    float startLength = bank_.LastLength(CumStart);
    if (startLength > 0.f) Logf("Playing start moan! Length: %.2fs", startLength);

    bank_.ResetCooldowns(CumWhile);
    cumMoanTimer_ = startLength;
}

void MoanLogic::OnCumEnd() {
    Logf("=== Cumming Ended ===");
    bank_.ResetCooldowns(CumWhile);

    if (cumMoanTimer_ > 0.f) {
        endMoanTimer_ = cumMoanTimer_;
        pendingEnd_ = true;
        Logf("Scheduled end moan in %.2fs (after current moan finishes)", endMoanTimer_);
    } else {
        PlayEndMoan();
    }
}

void MoanLogic::CumTick(float dt) {
    // pending end moan
    if (pendingEnd_) {
        endMoanTimer_ -= dt;
        if (endMoanTimer_ <= 0.f) {
            PlayEndMoan();
            pendingEnd_ = false;
            playingEnd_ = true;
        }
    }

    if (!cur_.cumming || !bank_.Has(CumWhile) || BreathActive()) return;

    cumMoanTimer_ -= dt;
    if (cumMoanTimer_ > 0.f) return;

    if (cur_.talking) {
        Logf("Skipping moan - robot is talking");
        cumMoanTimer_ = cumMoanCooldown_;
        return;
    }

    cumMoanCooldown_ = CumMoanFrequency();

    if (ShouldBreathe()) BreathStart([this] { PlayCummingMoan(); });
    else PlayCummingMoan();
}

void MoanLogic::PlayCummingMoan() {
    lastActionWasBreath_ = false;
    bank_.Play(CumWhile, true, 1.f);
    AddMoanTimestamp();

    float length = bank_.LastLength(CumWhile);
    cumMoanTimer_ = length + cumMoanCooldown_;
    Logf("Played moan '%s'! Clip: %.2fs, Cooldown: %.2fs, Next in: %.2fs", bank_.LastName(CumWhile).c_str(),
         length, cumMoanCooldown_, cumMoanTimer_);
}

void MoanLogic::PlayEndMoan() {
    bank_.Play(CumEnd, false, 1.f);
    Logf("Playing end moan!");
}

float MoanLogic::CumMoanFrequency() const {
    float lustNorm = Clamp01((cur_.lust - 10.f) / 1990.f);
    float sympathyNorm = Clamp01((cur_.sympathy - 5.f) / 1495.f);
    float factor = (lustNorm + sympathyNorm) / 2.f;

    float rangeMin = 1.0f - factor * 0.9f;
    float rangeMax = 1.8f - factor * 1.3f;
    float u = std::uniform_real_distribution<float>(0.f, 1.f)(rng_);
    return rangeMin + (rangeMax - rangeMin) * u;
}


// ===================== game.cpp =====================



namespace game {

static Il2CppClass* kBrain = nullptr;
static Il2CppClass* kGameScript = nullptr;
static Il2CppClass* kTime = nullptr;
static const MethodInfo* mTryGet = nullptr;
static const MethodInfo* mFrame = nullptr;
static const MethodInfo* mScale = nullptr;

static bool g_dumpWanted = false;
static bool g_dumped = false;
static bool g_loggedNoTryGet = false;

bool Init(bool dumpClasses) {
    g_dumpWanted = dumpClasses;
    if (!kBrain) kBrain = il2::FindClass("", "ModelBrain");
    if (!kGameScript) kGameScript = il2::FindClass("", "GameScript");
    if (!kTime) kTime = il2::FindClass("UnityEngine", "Time");

    if (!kBrain || !kGameScript) return false;

    mTryGet = il2::FindMethod(kBrain, "TryGet", 2);
    if (!mTryGet) {
        if (!g_loggedNoTryGet) {
            g_loggedNoTryGet = true;
            Logf("ModelBrain.TryGet(2 args) not found - the game's API differs from the PC version");
            il2::DumpClass(kBrain, "ModelBrain");
        }
        return false;
    }

    mFrame = il2::FindMethod(kTime, "get_frameCount", 0);
    mScale = il2::FindMethod(kTime, "get_timeScale", 0);
    Logf("Game classes found (Time.frameCount: %s, Time.timeScale: %s)", mFrame ? "yes" : "no", mScale ? "yes" : "no");
    return true;
}

static Il2CppObject* FetchBrain() {
    Il2CppObject* key = il2::NewString("bot");
    void* outObj = nullptr;
    void* args[2] = {key, &outObj};
    bool threw = false;
    Il2CppObject* r = il2::Invoke(mTryGet, nullptr, args, &threw);
    if (threw || !r) return nullptr;
    void* b = il2::Unbox(r);
    if (!b || *static_cast<uint8_t*>(b) == 0) return nullptr;
    return static_cast<Il2CppObject*>(outObj);
}

bool Capture(Ctx& c) {
    Il2CppObject* brain = FetchBrain();
    if (!brain) return false;

    c = Ctx{};
    double d = 0;

    if (il2::GetNumber(brain, "Pleasure", &d)) c.pleasure = (float)d;
    if (il2::GetNumber(brain, "IsTalkingWithOverlay", &d)) c.talking = d != 0;

    Il2CppObject* controller = nullptr;
    Il2CppObject* expression = nullptr;
    il2::GetRef(brain, "ConnectedController", &controller);
    if (controller) il2::GetRef(controller, "Expression", &expression);
    if (expression && il2::GetNumber(expression, "IsCumming", &d)) c.cumming = d != 0;

    Il2CppObject* state = nullptr;
    il2::GetRef(brain, "CurrentState", &state);
    if (state) {
        if (il2::IsInstanceOfName(state, "GenericFuckBrainState")) c.scene = SceneType::Generic;
        else if (il2::IsInstanceOfName(state, "CowgirlBrainState")) c.scene = SceneType::Cowgirl;
        else if (il2::IsInstanceOfName(state, "ShowerBrainState")) c.scene = SceneType::Shower;
    }

    Il2CppObject* script = nullptr;
    Il2CppObject* vars = nullptr;
    il2::GetStaticRef(kGameScript, "Instance", &script);
    if (script) il2::GetRef(script, "GameVariables", &vars);
    if (vars) {
        if (il2::GetNumber(vars, "lust", &d)) c.lust = (int)d;
        if (il2::GetNumber(vars, "sympathy", &d)) c.sympathy = (int)d;
        if (il2::GetNumber(vars, "IsBotSmart", &d)) c.advancedAi = d != 0;
    }

    if (g_dumpWanted && !g_dumped) {
        g_dumped = true;
        Logf("State sample: pleasure=%.3f cumming=%d talking=%d scene=%d lust=%d sympathy=%d smartAi=%d", c.pleasure,
             c.cumming, c.talking, (int)c.scene, c.lust, c.sympathy, c.advancedAi);
        il2::DumpClass(il2::ClassOf(brain), "ModelBrain (live object)");
        il2::DumpClass(il2::ClassOf(controller), "ConnectedController");
        il2::DumpClass(il2::ClassOf(expression), "Expression");
        il2::DumpClass(il2::ClassOf(state), "CurrentState");
        il2::DumpClass(il2::ClassOf(script), "GameScript instance");
        il2::DumpClass(il2::ClassOf(vars), "GameVariables");
    }
    return true;
}

bool Heartbeat(int* frameCount, float* timeScale) {
    double d = 0;
    if (!mFrame || !il2::CallStaticNumber(mFrame, &d)) return false;
    *frameCount = (int)d;
    *timeScale = 1.f;
    if (mScale && il2::CallStaticNumber(mScale, &d)) *timeScale = (float)d;
    return true;
}

}  // namespace game


// ===================== main.cpp =====================
// MoanMod for Android (native). Loaded into the game process as a dependency of libmain.so;
// the constructor below starts a background thread that reads the game state through the IL2CPP API
// and plays the moan sounds itself (OpenSL ES).
#include <dirent.h>
#include <errno.h>
#include <sys/stat.h>
#include <strings.h>
#include <unistd.h>

#include <algorithm>
#include <chrono>
#include <cstdio>
#include <random>
#include <string>
#include <thread>
#include <vector>






using Clock = std::chrono::steady_clock;

static void SleepMs(int ms) { std::this_thread::sleep_for(std::chrono::milliseconds(ms)); }

static std::string ReadProcessName() {
    char buf[256] = {0};
    FILE* f = fopen("/proc/self/cmdline", "r");
    if (!f) return "";
    size_t n = fread(buf, 1, sizeof(buf) - 1, f);
    fclose(f);
    buf[n] = 0;
    return buf;
}

static bool MakeDirs(const std::string& path) {
    for (size_t i = 1; i <= path.size(); i++) {
        if (i == path.size() || path[i] == '/') mkdir(path.substr(0, i).c_str(), 0775);
    }
    return access(path.c_str(), W_OK) == 0;
}

// Folder for config, log and the .wav files. Prefer the app's external files dir (reachable from a
// file manager / USB), fall back to the private one.
static std::string ResolveBase(const std::string& pkg) {
    const std::string candidates[] = {
        "/storage/emulated/0/Android/data/" + pkg + "/files/MoanMod",
        "/data/user/0/" + pkg + "/files/MoanMod",
        "/data/data/" + pkg + "/files/MoanMod",
    };
    for (const auto& c : candidates)
        if (MakeDirs(c)) return c;
    return candidates[0];
}

static std::vector<std::string> ListWavs(const std::string& dir) {
    std::vector<std::string> out;
    DIR* d = opendir(dir.c_str());
    if (!d) return out;
    while (dirent* e = readdir(d)) {
        std::string n = e->d_name;
        if (n.size() > 4 && strcasecmp(n.c_str() + n.size() - 4, ".wav") == 0) out.push_back(dir + "/" + n);
    }
    closedir(d);
    std::sort(out.begin(), out.end());
    return out;
}

static size_t LoadAllAudio(const std::string& base, AudioBank& bank) {
    struct Map { const char* sub; AType type; const char* label; };
    const Map maps[] = {
        {"cumming/start", CumStart, "CumStart"}, {"cumming/while", CumWhile, "CumWhile"},
        {"cumming/end", CumEnd, "CumEnd"},       {"while", Sex, "Sex"},
        {"breath", Breath, "Breath"},
    };

    bank.Clear();
    size_t total = 0;
    for (const auto& m : maps) {
        MakeDirs(base + "/" + m.sub);
        for (const auto& file : ListWavs(base + "/" + m.sub)) {
            std::string err;
            auto clip = LoadWav(file, &err);
            if (!clip) { Logf("Failed to load %s: %s", file.c_str(), err.c_str()); continue; }
            bank.Add(m.type, clip);
            total++;
        }
        Logf("Loaded %d %s clips", bank.Count(m.type), m.label);
    }
    if (!bank.Has(CumWhile)) Logf("WARNING: no .wav files in cumming/while (put them in %s/cumming/while)", base.c_str());
    return total;
}

static void Run() {
    const std::string pkg = ReadProcessName();
    if (pkg.empty() || pkg.find(':') != std::string::npos) return;  // only the main game process

    // Preferred data folder: Android/media/<package>/MoanMod. Unlike Android/data it can be opened with any file
    // manager (no Shizuku / "access denied" problems), and the app may create it itself.
    // Fallbacks: Android/data/<package>/files/MoanMod, then the private folder.
    std::string base;
    const std::string mediaDir = "/storage/emulated/0/Android/media/" + pkg + "/MoanMod";
    const std::string dataDir = "/storage/emulated/0/Android/data/" + pkg + "/files/MoanMod";
    for (int i = 0; i < 20 && base.empty(); i++) {
        if (MakeDirs(mediaDir)) base = mediaDir;
        else SleepMs(1000);
    }
    // the app's external files folder may not exist yet on the very first launch, so wait for it
    for (int i = 0; i < 60 && base.empty(); i++) {
        if (MakeDirs(dataDir)) base = dataDir;
        else SleepMs(1000);
    }
    if (base.empty()) base = ResolveBase(pkg);
    LogInit(base + "/moanmod.log");
    Logf("==== MoanMod native starting (package %s) ====", pkg.c_str());
    Logf("Data folder: %s", base.c_str());

    Config cfg;
    LoadConfig(base + "/config.ini", cfg);
    if (!cfg.enabled) { Logf("Disabled in config.ini"); return; }

    while (!il2::Init()) SleepMs(500);
    while (!il2::DomainReady()) SleepMs(500);
    Logf("IL2CPP runtime is up; giving it a few seconds to finish initialising");
    SleepMs(6000);
    il2::AttachThread();

    while (!game::Init(cfg.dumpClasses)) SleepMs(3000);

    if (!g_mixer.Start()) Logf("Audio output could not be started - no sound will play");

    std::mt19937 rng((unsigned)Clock::now().time_since_epoch().count());
    AudioBank bank(cfg, &g_mixer, rng);
    MoanLogic logic(cfg, bank, rng);
    size_t total = LoadAllAudio(base, bank);

    auto last = Clock::now();
    auto lastFrameChange = last;
    auto lastScan = last;
    int lastFrame = -1;
    bool paused = false;
    bool brainFound = false;

    Logf("Main loop running");
    for (;;) {
        SleepMs(30);
        auto now = Clock::now();
        float dt = std::chrono::duration<float>(now - last).count();
        last = now;
        if (dt > 0.25f) dt = 0.25f;

        // app in background / frozen -> stop sound and timers
        int frame = 0;
        float scale = 1.f;
        if (game::Heartbeat(&frame, &scale)) {
            if (frame != lastFrame) {
                lastFrame = frame;
                lastFrameChange = now;
                if (paused) { paused = false; Logf("Game resumed"); }
            } else if (!paused && std::chrono::duration<float>(now - lastFrameChange).count() > 0.6f) {
                paused = true;
                g_mixer.StopAll();
                Logf("Game paused/backgrounded");
            }
        }
        if (paused) continue;

        if (total == 0 && std::chrono::duration<float>(now - lastScan).count() > 5.f) {
            lastScan = now;
            total = LoadAllAudio(base, bank);  // let the user add files without restarting
        }

        Ctx ctx;
        if (!game::Capture(ctx)) { brainFound = false; continue; }
        if (!brainFound) {
            brainFound = true;
            Logf("Found ModelBrain!");
            logic.OnBrainFound();
        }
        logic.Update(ctx, dt * (scale < 0.f ? 0.f : scale));
    }
}

__attribute__((constructor)) static void MoanModEntry() {
    std::thread([] {
        try {
            Run();
        } catch (...) {
            Logf("MoanMod thread stopped by an exception");
        }
    }).detach();
}

